from pathlib import Path
import re

p=Path('experience.html')
text=p.read_text(encoding='utf-8')

section_re=re.compile(r'<section class="decisionBox expTabPanel" id="formatFinder" data-exp-panel="recommend">.*?</section>',re.S)
section='''<section class="decisionBox expTabPanel" id="formatFinder" data-exp-panel="recommend"><h2>作品から上映方式を選ぶ</h2><p>作品名を入力すると候補が表示されます。正しい作品を選んでからおすすめを表示します。</p><div class="filmPicker livePicker"><input id="formatFilm" type="search" placeholder="作品名を入力（例：スター・ウォーズ）" aria-label="上映方式を選ぶ作品名" autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="formatCandidates" aria-expanded="false"></div><div class="filmCandidates" id="formatCandidates" role="listbox" hidden></div><button id="formatConfirm" class="formatConfirm" type="button" disabled hidden>この作品でおすすめを見る</button><div class="formatResult" id="formatResult"><div class="decisionNote">2文字以上入力すると候補が表示されます。</div></div></section>'''
text,n=section_re.subn(section,text,count=1)
if n!=1: raise SystemExit('formatFinder section not found')

if 'experience-live-candidates-v2' not in text:
    css='''<style id="experience-live-candidates-v2">\n.livePicker{display:block}.livePicker input{width:100%}.filmCandidates{position:relative;z-index:4;border:1px solid #30343a;border-radius:10px;overflow:hidden;background:#090b0e}.filmCandidate{border:0!important;border-bottom:1px solid #24282e!important;border-radius:0!important}.filmCandidate:last-child{border-bottom:0!important}.candidateState{padding:10px 11px;color:#858d96;font-size:11px}.formatConfirm{margin-top:10px}.formatEvidence{margin-top:5px;padding:8px 9px;border-left:2px solid #59616b;background:#0a0c0f;color:#aeb5bd;font-size:10px;line-height:1.55}\n</style>\n'''
    text=text.replace('<style id="experience-tabs-v1">',css+'<style id="experience-tabs-v1">',1)

script_re=re.compile(r'<script id="experience-decision-js-v1">.*?</script>',re.S)
script=r'''<script id="experience-decision-js-v1">(()=>{const input=document.getElementById('formatFilm'),confirmBtn=document.getElementById('formatConfirm'),candidateBox=document.getElementById('formatCandidates'),out=document.getElementById('formatResult');if(!input||!confirmBtn||!candidateBox||!out)return;let candidates=[];let selectedMovie=null;let candidateTimer=null;let candidateRequest=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const clamp=n=>Math.max(1,Math.min(5,n));const stars=n=>'★'.repeat(Math.round(n))+'☆'.repeat(5-Math.round(n));function movieYear(m){const d=m.release_date||m.first_air_date||m.year||'';return String(d).slice(0,4)}function genresOf(m){return (m.genres||m.genre_names||[]).map(x=>String(typeof x==='string'?x:(x&&x.name)||'').toLowerCase()).join(' ')}function scoreMovie(m){const g=genresOf(m),s={'通常上映':4,'IMAX':3.5,'Dolby Cinema':3.5,'4DX / MX4D':2,'ScreenX':2};if(/action|アクション|adventure|アドベンチャー|science fiction|sf|fantasy|ファンタジー/.test(g)){s.IMAX+=1;s['Dolby Cinema']+=.5;s['4DX / MX4D']+=.8;s.ScreenX+=.4}if(/horror|ホラー|thriller|スリラー|crime|犯罪/.test(g)){s['Dolby Cinema']+=1;s.IMAX+=.3;s['4DX / MX4D']+=.3}if(/animation|アニメ/.test(g)){s.IMAX+=.6;s['Dolby Cinema']+=.5;s.ScreenX+=.2}if(/drama|ドラマ|romance|恋愛|documentary|ドキュメンタリー/.test(g)){s['通常上映']+=.5;s['Dolby Cinema']+=.2;s['4DX / MX4D']-=.8;s.ScreenX-=.5}Object.keys(s).forEach(k=>s[k]=clamp(s[k]));return s}function summary(k){return k==='IMAX'?'大画面・スケール感を重視':k==='Dolby Cinema'?'黒・コントラストと立体音響を重視':k==='4DX / MX4D'?'座席の動きと環境効果を重視':k==='ScreenX'?'左右へ広がる視界を重視':'追加演出なしで作品に集中'}function tabFor(k){return k==='IMAX'?'aspect':k==='Dolby Cinema'?'visual':k==='4DX / MX4D'||k==='ScreenX'?'special':null}function tabLabel(k){return k==='IMAX'?'画角を詳しく見る':k==='Dolby Cinema'?'映像を詳しく見る':k==='4DX / MX4D'||k==='ScreenX'?'体感を詳しく見る':''}function evidenceFor(m,k){const raw=[...(Array.isArray(m.formats)?m.formats:[]),...(Array.isArray(m.screening_formats)?m.screening_formats:[]),...(Array.isArray(m.special_formats)?m.special_formats:[])].map(String).join(' ').toLowerCase();if(k==='IMAX'&&(m.imax===true||raw.includes('imax')))return '作品データ上でIMAXに関する明示情報を確認できたため、IMAXを候補として評価しています。';if(k==='Dolby Cinema'&&(m.dolby_cinema===true||raw.includes('dolby cinema')))return '作品データ上でDolby Cinemaに関する明示情報を確認できたため、Dolby Cinemaを候補として評価しています。';if(k==='ScreenX'&&(m.screenx===true||raw.includes('screenx')))return '作品データ上でScreenXに関する明示情報を確認できたため、ScreenXを候補として評価しています。';if(k==='4DX / MX4D'&&(m.fourdx===true||m.mx4d===true||raw.includes('4dx')||raw.includes('mx4d')))return '作品データ上で4DX / MX4Dに関する明示情報を確認できたため、体感上映を候補として評価しています。';return ''}function normalizePayload(d){const pools=[];if(Array.isArray(d))pools.push(d);if(Array.isArray(d?.movies))pools.push(d.movies);if(Array.isArray(d?.external))pools.push(d.external);if(Array.isArray(d?.results))pools.push(d.results);if(Array.isArray(d?.items))pools.push(d.items);return pools.flat()}function renderCandidates(){candidateBox.innerHTML=candidates.map((m,i)=>'<button type="button" class="filmCandidate" role="option" data-candidate-index="'+i+'"><b>'+esc(m.title||m.name||'タイトル不明')+'</b><span>'+esc(movieYear(m)||'年不明')+'</span></button>').join('');candidateBox.hidden=!candidates.length;input.setAttribute('aria-expanded',candidates.length?'true':'false');candidateBox.querySelectorAll('[data-candidate-index]').forEach(el=>el.addEventListener('click',()=>{const i=Number(el.dataset.candidateIndex);selectedMovie=candidates[i];input.value=selectedMovie.title||selectedMovie.name||input.value;candidateBox.hidden=true;input.setAttribute('aria-expanded','false');confirmBtn.disabled=false;confirmBtn.hidden=false;out.innerHTML='<div class="decisionNote"><b>'+esc(selectedMovie.title||selectedMovie.name||input.value)+'</b>を選択しました。「この作品でおすすめを見る」を押してください。</div>'}))}async function loadCandidates(){const q=input.value.trim();if(q.length<2){candidates=[];candidateBox.hidden=true;input.setAttribute('aria-expanded','false');return}if(candidateRequest)candidateRequest.abort();candidateRequest=new AbortController();candidateBox.hidden=false;candidateBox.innerHTML='<div class="candidateState">候補を検索中…</div>';input.setAttribute('aria-expanded','true');try{const r=await fetch('https://backend-one-gray-94.vercel.app/api/movies?q='+encodeURIComponent(q)+'&limit=8',{cache:'no-store',signal:candidateRequest.signal});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json(),seen=new Set();candidates=normalizePayload(d).filter(m=>{const key=String(m.tmdbId||m.id||'')+'|'+String(m.title||m.name||'')+'|'+movieYear(m);if(seen.has(key))return false;seen.add(key);return m&&(m.title||m.name)}).slice(0,6);if(!candidates.length){candidateBox.innerHTML='<div class="candidateState">候補が見つかりませんでした。</div>';return}renderCandidates()}catch(e){if(e.name==='AbortError')return;candidateBox.hidden=false;candidateBox.innerHTML='<div class="candidateState">候補を取得できませんでした。入力を変えてお試しください。</div>';input.setAttribute('aria-expanded','true')}}function renderRecommendation(){if(!selectedMovie)return;candidateBox.hidden=true;input.setAttribute('aria-expanded','false');const scores=scoreMovie(selectedMovie),rows=[['通常上映',scores['通常上映']],...Object.entries(scores).filter(([k])=>k!=='通常上映').sort((a,b)=>b[1]-a[1])],title=selectedMovie.title||selectedMovie.name||input.value.trim();out.innerHTML='<div class="decisionNote"><b>'+esc(title)+'</b>の作品傾向からの目安</div>'+rows.map(([k,v])=>{const target=tabFor(k),tabLink=target?'<button type="button" class="formatScoreCta" data-go-tab="'+target+'">'+tabLabel(k)+' →</button>':'',evidence=evidenceFor(selectedMovie,k),evidenceHtml=evidence?'<span class="formatEvidence"><b>確認できた根拠</b><br>'+esc(evidence)+'</span>':'';return '<div class="formatScore"><b>'+k+'</b><strong>'+stars(v)+'</strong><span class="formatScoreMeta"><span>'+summary(k)+'</span><span class="formatScoreActions">'+tabLink+'</span>'+evidenceHtml+'</span></div>'}).join('')+'<div class="decisionNote">※星はジャンル等からの相性目安です。「理由」は確認できる作品固有の根拠がある場合のみ表示します。作品固有の上映仕様・上映有無は劇場公式情報を確認してください。</div>';out.querySelectorAll('[data-go-tab]').forEach(el=>el.addEventListener('click',()=>window.switchExperienceTab&&window.switchExperienceTab(el.dataset.goTab,true)))}input.addEventListener('input',()=>{selectedMovie=null;confirmBtn.disabled=true;confirmBtn.hidden=true;out.innerHTML='<div class="decisionNote">候補から作品を選んでください。</div>';clearTimeout(candidateTimer);candidateTimer=setTimeout(loadCandidates,250)});input.addEventListener('focus',()=>{if(candidates.length&&!selectedMovie){candidateBox.hidden=false;input.setAttribute('aria-expanded','true')}});confirmBtn.addEventListener('click',renderRecommendation)})();</script>'''
text,n=script_re.subn(script,text,count=1)
if n!=1: raise SystemExit('decision script not found')

p.write_text(text,encoding='utf-8')
